            {
                return (BracketedParameterListSyntax)this.EatNode();
            }
            var parameters = this.ParseParameterList(out var open, out var close, SyntaxKind.OpenBracketToken, SyntaxKind.CloseBracketToken, forExtensionOrUnion: false);
