            if (list.OpenParenToken.IsMissing)
            {
                return false;
            }
            if (list.CloseParenToken.IsMissing)
            {
                return false;
            }
            foreach (var parameter in list.Parameters)
            {
                if (!CanReuseParameter(parameter, identifierIsOptional))
                {
                    return false;
                }
            }
            return true;
        }
        private static bool CanReuseBracketedParameterList(Syntax.BracketedParameterListSyntax list)
        {
            if (list == null)
            {
                return false;
            }
            if (list.OpenBracketToken.IsMissing)
            {
                return false;
            }
            if (list.CloseBracketToken.IsMissing)
            {
                return false;
            }
            foreach (var parameter in list.Parameters)
            {
                if (!CanReuseParameter(parameter, identifierIsOptional: false))
                {
                    return false;
                }
            }
            return true;
        }
