                            continue;
                        case SyntaxKind.PlusPlusToken:
                        case SyntaxKind.MinusMinusToken:
                            expr = _syntaxFactory.PostfixUnaryExpression(SyntaxFacts.GetPostfixUnaryExpression(this.CurrentToken.Kind), expr, this.EatToken());
