            if (precedence > Precedence.Lambda)
                return false;
            var index = 1;
            while (true)
            {
                var token = this.PeekToken(index++);
                if (this.IsTrueIdentifier(token) ||
                    token.Kind is SyntaxKind.CommaToken ||
                    IsParameterModifierIncludingScoped(token))
