            {
                if (!isBinaryPatternKeyword())
                {
                    return false;
                }
                bool lastTokenIsBinaryOperator = true;
                EatToken();
                while (isBinaryPatternKeyword())
                {
                    lastTokenIsBinaryOperator = !lastTokenIsBinaryOperator;
                    EatToken();
                }
                return lastTokenIsBinaryOperator == IsPossibleSubpatternElement();
